-- HIT - Bounce 핵심역량 해설 모듈 24개 (6 역량 × 4 등급) — 2026-10-12 (세션 169)
-- 옛 COMP-* (분석·소통·창의·실행·리더십·기획 6영역 문안)은 핵심역량 6과 1:1이 아니어서 대체 (docs/HIT_Result_Analysis_Review_2026-10.md R1)
-- 등급 = 화면 점수 구간과 같음: A 75+ 뚜렷한 강점 · B 50~74 갖춰짐 · C 25~49 보완하면 좋음 · D 25 미만 우선 보완
-- 선택: lib/hit/report-assembler.ts selectBModules → CORE-{PROBLEM|COMM|INIT|COLLAB|SELF|AGILE}-{A..D}
-- 재실행 가능 (ON CONFLICT 갱신). 롤백: DELETE FROM hit_report_modules WHERE id LIKE 'CORE-%';

INSERT INTO public.hit_report_modules (id, category, title, content) VALUES
-- 문제해결
('CORE-PROBLEM-A', 'core_competency', '문제해결 — 뚜렷한 강점', '복잡한 상황에서도 무엇이 진짜 문제인지 먼저 짚고, 원인을 나눠 보고, 해결 방향을 세우는 힘이 뚜렷합니다. 팀 과제나 프로젝트에서 막힌 지점을 정리해 다시 움직이게 하는 역할을 자연스럽게 맡게 됩니다. 이 강점은 기획·전략·데이터 직무에서 특히 빛납니다. 다음 단계는 내가 푼 문제를 "문제 → 원인 → 해결 → 결과" 한 장으로 남겨 두는 것입니다. 면접에서 가장 설득력 있는 근거가 됩니다.'),
('CORE-PROBLEM-B', 'core_competency', '문제해결 — 갖춰짐', '익숙한 유형의 문제는 스스로 풀어냅니다. 다만 처음 보는 문제를 만나면 바로 해결책부터 찾으려다 원인을 놓칠 때가 있을 수 있습니다. 문제를 만나면 먼저 "무엇이 문제인가"를 한 문장으로 적고, 가능한 원인을 세 가지 이상 나열해 보세요. 이 습관 하나로 해결의 질이 눈에 띄게 달라집니다.'),
('CORE-PROBLEM-C', 'core_competency', '문제해결 — 보완하면 좋음', '문제를 마주하면 어디서부터 손대야 할지 막막함이 먼저 올 수 있습니다. 문제해결은 타고나는 감각보다 순서를 익히는 기술에 가깝습니다. 작은 문제부터 "현상 → 원인 → 대안 → 선택 이유" 네 칸을 채워 보세요. 팀 과제에서 정리 역할을 한 번 맡아 보는 것도 빠르게 느는 방법입니다.'),
('CORE-PROBLEM-D', 'core_competency', '문제해결 — 우선 보완', '지금은 문제를 스스로 정의하고 푸는 경험이 아직 적은 상태일 수 있습니다. 괜찮습니다 — 경험이 쌓이면 가장 빨리 오르는 역량입니다. 이번 주에 겪은 불편 하나를 골라 "왜 생겼을까"를 세 번 물어보는 연습부터 시작해 보세요. 혼자 막힐 때는 잘 푸는 사람이 어떤 순서로 생각하는지 옆에서 관찰하는 것이 큰 도움이 됩니다.'),
-- 소통
('CORE-COMM-A', 'core_competency', '소통 — 뚜렷한 강점', '생각을 상대가 이해하기 쉽게 정리해 전하고, 상대의 말에서 핵심을 정확히 듣는 힘이 뛰어납니다. 발표·설득·조율이 필요한 자리에서 자연스럽게 앞에 서게 됩니다. 광고·영업·기획처럼 사람을 움직여야 하는 직무에서 큰 무기가 됩니다. 다음 단계는 듣는 사람에 따라 같은 내용을 다르게 전하는 연습입니다 — 임원용 한 줄, 실무자용 세 줄처럼요.'),
('CORE-COMM-B', 'core_competency', '소통 — 갖춰짐', '일상적인 대화와 1:1 소통은 편안하게 해냅니다. 여러 사람 앞에서 말하거나 반대 의견을 설득해야 할 때는 아직 부담이 남아 있을 수 있습니다. 말하기 전에 결론을 먼저 한 문장으로 정하고, 근거를 두세 가지 붙이는 순서로 연습해 보세요. 발표 기회를 일부러 한 번 더 잡는 것이 가장 빠른 성장 방법입니다.'),
('CORE-COMM-C', 'core_competency', '소통 — 보완하면 좋음', '생각은 분명히 있는데 말이나 글로 꺼내는 데 시간이 걸리거나, 상대가 내 뜻을 다르게 받아들인 경험이 있을 수 있습니다. 소통은 연습량이 그대로 실력이 되는 역량입니다. 회의 전에 말할 내용을 세 줄로 적어 가고, 대화 끝에 "제가 이해한 건 ~인데 맞나요?"라고 확인해 보세요. 오해가 줄고 신뢰가 쌓입니다.'),
('CORE-COMM-D', 'core_competency', '소통 — 우선 보완', '지금은 생각을 말로 꺼내는 것 자체가 부담스러운 상태일 수 있습니다. 내향적인 성향과 소통 역량은 다른 이야기입니다 — 조용한 사람도 잘 전달할 수 있습니다. 먼저 글로 정리하는 데서 시작해 보세요. 메신저로 결론부터 짧게 쓰는 연습, 그리고 작은 모임에서 한 번 의견을 말해 보는 것이 첫걸음입니다.'),
-- 주도성
('CORE-INIT-A', 'core_competency', '주도성 — 뚜렷한 강점', '시키기 전에 할 일을 찾고 먼저 움직이는 힘이 뚜렷합니다. 새 프로젝트를 제안하고 끌고 가는 역할에서 에너지를 얻습니다. 스타트업·신사업·캠페인 기획처럼 정해진 길이 없는 일에 잘 맞습니다. 다만 혼자 앞서 나가면 팀이 따라오지 못할 수 있으니, 시작할 때 목표와 역할을 함께 정리하는 습관을 더하면 강점이 리더십으로 이어집니다.'),
('CORE-INIT-B', 'core_competency', '주도성 — 갖춰짐', '맡은 일은 책임 있게 해내고, 필요할 때는 먼저 움직이기도 합니다. 다만 기회가 보여도 "내가 해도 될까" 망설이는 순간이 있을 수 있습니다. 이번 달에 작은 것 하나를 먼저 제안해 보세요 — 회의 진행, 자료 정리, 새 아이디어 무엇이든 좋습니다. 먼저 손을 든 경험이 쌓이면 주도성은 금방 강점이 됩니다.'),
('CORE-INIT-C', 'core_competency', '주도성 — 보완하면 좋음', '분명한 지시와 역할이 있을 때 더 편하게 움직이는 편일 수 있습니다. 이것은 성실함의 다른 면이기도 합니다. 주도성을 키우려면 큰 결심보다 작은 시작이 필요합니다. 스스로 정한 작은 목표 하나를 일주일 안에 끝내 보고, 끝낸 것을 기록해 두세요. 스스로 시작해서 끝낸 경험이 다음 시작을 쉽게 만듭니다.'),
('CORE-INIT-D', 'core_competency', '주도성 — 우선 보완', '지금은 먼저 나서는 것이 부담스럽거나, 무엇을 해야 할지 정하기 어려운 시기일 수 있습니다. 주도성은 성격이 아니라 경험으로 자랍니다. 오늘 할 일 한 가지를 스스로 정하고 끝내는 것부터 시작해 보세요. 동아리나 스터디에서 아주 작은 역할 하나를 자원하는 것도 좋은 첫걸음입니다.'),
-- 협업
('CORE-COLLAB-A', 'core_competency', '협업 — 뚜렷한 강점', '팀 안에서 역할을 나누고, 서로 다른 의견을 맞추며, 함께 결과를 만드는 힘이 뛰어납니다. 함께 일하는 사람들이 편안함을 느끼고, 팀 분위기가 좋아집니다. 여러 부서·파트너와 맞물려 일하는 직무에서 특히 중요한 강점입니다. 다음 단계는 의견이 크게 갈릴 때 결론을 이끌어 내는 경험입니다 — 조율자에서 결정자로 한 걸음 나아가 보세요.'),
('CORE-COLLAB-B', 'core_competency', '협업 — 갖춰짐', '함께 일하는 데 큰 어려움이 없고 맡은 역할을 잘 해냅니다. 의견이 다를 때 내 생각을 말하기보다 맞춰 주는 쪽을 택하거나, 반대로 내 방식을 고집할 때가 있을 수 있습니다. 의견이 갈리면 먼저 상대 입장을 한 문장으로 정리해 말해 보세요. 상대가 존중받는다고 느끼면 합의가 훨씬 쉬워집니다.'),
('CORE-COLLAB-C', 'core_competency', '협업 — 보완하면 좋음', '혼자 하는 편이 더 빠르고 편하다고 느낄 때가 많을 수 있습니다. 혼자 몰입하는 힘은 강점이지만, 대부분의 일은 결국 함께 완성됩니다. 팀 과제에서 진행 상황을 먼저 공유하고, 도움이 필요한 부분을 일찍 말하는 연습을 해 보세요. 작은 공유가 신뢰를 만들고 협업을 편하게 합니다.'),
('CORE-COLLAB-D', 'core_competency', '협업 — 우선 보완', '지금은 함께 일하는 과정에서 피로나 갈등을 크게 느끼는 상태일 수 있습니다. 협업은 성격보다 방법의 문제인 경우가 많습니다. 역할과 마감을 처음에 분명히 정하고, 정해진 것을 지키는 것부터 시작해 보세요. 신뢰할 수 있는 한 사람과 작은 일을 함께 끝내 보는 경험이 출발점이 됩니다.'),
-- 자기관리
('CORE-SELF-A', 'core_competency', '자기관리 — 뚜렷한 강점', '시간·에너지·감정을 스스로 관리해 꾸준히 해내는 힘이 뚜렷합니다. 마감이 겹치고 여러 일을 동시에 다뤄야 하는 환경에서도 흔들림이 적습니다. 주변에서 "믿고 맡길 수 있는 사람"으로 기억됩니다. 다음 단계는 이 리듬을 팀에도 나누는 것입니다 — 일정 관리 방식을 공유하면 팀 전체의 속도가 올라갑니다.'),
('CORE-SELF-B', 'core_competency', '자기관리 — 갖춰짐', '해야 할 일은 대체로 해내지만, 일이 몰리거나 컨디션이 떨어지면 리듬이 흔들릴 때가 있을 수 있습니다. 아침에 오늘 꼭 할 일 세 가지만 정하고, 저녁에 한 번 확인하는 습관을 들여 보세요. 지칠 때 회복하는 나만의 방법을 미리 정해 두는 것도 꾸준함을 지키는 데 큰 도움이 됩니다.'),
('CORE-SELF-C', 'core_competency', '자기관리 — 보완하면 좋음', '마감 직전에 몰아서 하거나, 계획을 세워도 지키기 어려운 경험이 반복될 수 있습니다. 의지의 문제라기보다 방법의 문제인 경우가 많습니다. 일주일 단위로 "꼭 할 일 한 가지"만 정하고 지켜 보세요. 작은 약속을 지킨 경험이 쌓이면 큰 계획도 지킬 수 있게 됩니다.'),
('CORE-SELF-D', 'core_competency', '자기관리 — 우선 보완', '지금은 일정과 컨디션이 자주 흔들리고, 스스로를 다잡기 어려운 시기일 수 있습니다. 먼저 수면과 하루 리듬처럼 기본부터 지켜 보세요. 할 일은 크게 세우지 말고 오늘 끝낼 수 있는 것 하나로 줄이는 것이 좋습니다. 필요하면 함께 점검해 줄 사람이나 나의 저니의 체크인을 활용하세요.'),
-- 학습민첩성
('CORE-AGILE-A', 'core_competency', '학습민첩성 — 뚜렷한 강점', '처음 하는 일과 새로운 도구를 빠르게 익히고, 경험에서 교훈을 뽑아내는 힘이 뛰어납니다. 변화가 잦은 직무, 그리고 무엇이든 처음 배우는 신입 시기에 가장 큰 무기가 됩니다. 디지털 마케팅·IT처럼 도구와 방식이 계속 바뀌는 분야와 잘 맞습니다. 다음 단계는 배운 것을 정리해 남에게 가르쳐 보는 것입니다 — 가르치면 내 것이 됩니다.'),
('CORE-AGILE-B', 'core_competency', '학습민첩성 — 갖춰짐', '필요한 것은 배워서 해내는 힘이 있습니다. 다만 배운 것을 돌아보고 다음에 적용하는 과정은 아직 습관이 되지 않았을 수 있습니다. 새 일을 하나 끝낼 때마다 "잘된 점 하나, 다음에 바꿀 점 하나"를 짧게 기록해 보세요. 이 기록이 쌓이면 배우는 속도가 눈에 띄게 빨라집니다.'),
('CORE-AGILE-C', 'core_competency', '학습민첩성 — 보완하면 좋음', '처음 하는 일 앞에서 부담이 커서 익숙한 방식으로 돌아가고 싶어질 때가 있을 수 있습니다. 새로 배울 것을 작게 쪼개면 부담이 줄어듭니다. 배우고 싶은 도구나 기술 하나를 골라 일주일에 한 조각씩 익혀 보세요. 모르는 것을 빨리 물어보는 것도 학습민첩성의 중요한 부분입니다.'),
('CORE-AGILE-D', 'core_competency', '학습민첩성 — 우선 보완', '지금은 새로운 것을 배우는 일 자체가 버겁게 느껴지는 시기일 수 있습니다. 배우는 속도는 사람마다 다르고, 방법을 바꾸면 달라집니다. 이미 잘하는 것 하나와 연결된 새 기술부터 시작해 보세요. 영상 하나, 실습 하나처럼 아주 작은 단위로 시작해 "배워서 해냈다"는 경험을 먼저 만드는 것이 중요합니다.')
ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, title = EXCLUDED.title, content = EXCLUDED.content, updated_at = now();
